import hashlib,json,subprocess,time
from pathlib import Path
root=Path.cwd();out=root/'build/rpp5hc-evidence';manifest=out/'sources-final.sha256';obj=root/'build/tests/CMakeFiles/libdxfrw_test_adapter.dir/__/dwg2dxf/dx_iface.cpp.o';lib=root/'build/libdxfrw.a';prior=json.loads((root/'docs/research/rpp5hb-classic-attribute-dual280-readiness-2026-10-28.json').read_text())
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
for line in manifest.read_text().splitlines():
 h,n=line.split(None,1);assert sha(root/n)==h,n
builds=[];results=[]
for kind in ('attdef','attrib'):
 src=out/(kind+'-source-probe.cpp');exe=out/(kind+'-source-probe');cmd=['/usr/bin/clang++','-std=c++17','-Wall','-Wextra','-Werror','-I.','-Isrc','-Ibuild',str(src),str(obj),str(lib),'-o',str(exe)]
 start=time.monotonic();b=subprocess.run(cmd,text=True,capture_output=True);assert b.returncode==0,b.stderr
 builds.append({'kind':kind,'command':cmd,'exitCode':b.returncode,'seconds':time.monotonic()-start,'sourceSha256':sha(src),'executableSha256':sha(exe)})
 for version in ('AC1024','AC1027','AC1032'):
  sample=prior['samples'][version];path=Path(sample['path']);assert sha(path)==sample['hash'];offset=sample['attdef' if kind=='attdef' else 'attrib'][0]
  command=[str(exe),str(path),version[2:],str(offset)];r=subprocess.run(command,text=True,capture_output=True);assert r.returncode==0,(command,r.stdout,r.stderr)
  results.append({'kind':kind,'version':version,'sourcePath':str(path),'sourceSha256':sha(path),'recordSpan':sample['attdef' if kind=='attdef' else 'attrib'],'command':command,'exitCode':r.returncode,'stdout':r.stdout,'stderr':r.stderr})
for line in manifest.read_text().splitlines():
 h,n=line.split(None,1);assert sha(root/n)==h,n
