#include "intern/dxfparserlimits.h"
#include "dwg2dxf/dx_attdef_source_profile.h"
#include "dwg2dxf/dx_iface.h"
#include "dwg2dxf/dx_data.h"
#include <cstdint>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
class DxIfaceTableSourceTestAccess {
public:
    static void inspect(const dx_data& data,unsigned& rows,bool& pair,bool& replay,bool& profile,bool& sourceRoles) {
        const auto found=data.m_tableDxfSource.resources.find(0x6f8u);
        if(found==data.m_tableDxfSource.resources.end())return;
        const auto& row=found->second;++rows;pair=row.attdefPairMatched;replay=row.attdefFieldsMatched&&!row.attdefFieldMismatch;
        profile=row.attdefProfile.complete();
        sourceRoles=profile&&row.raw&&row.raw->groups.size()==16u&&row.attdefProfile.spans.size()==16u
            &&row.attdefProfile.spans[11].field==dx_attdef_source::Field::ReservedDefault
            &&row.attdefProfile.spans[15].field==dx_attdef_source::Field::Attribute;
    }
};
int main(int argc,char** argv) {
    if(argc!=4)return 2;
    std::ifstream input(argv[1],std::ios::binary);if(!input)return 2;
    input.seekg(std::stoll(argv[3]));std::string bytes(190,'\0');input.read(&bytes[0],190);
    if(input.gcount()!=190)return 2;
    std::istringstream stream(bytes);std::string codeText,value;DRW_RawDxfObject raw;
    raw.name="ATTDEF";raw.handle=0x6f8u;raw.parentHandle=0x6f2u;raw.m_version=std::string(argv[2])=="1024"?DRW::AC1024:std::string(argv[2])=="1027"?DRW::AC1027:DRW::AC1032;
    while(std::getline(stream,codeText)&&std::getline(stream,value)) {
        const int code=std::stoi(codeText);if(code==0)continue;
        if(code==10||code==20||code==30||code==40)raw.groups.emplace_back(code,std::stod(value));
        else if(code==70||code==280)raw.groups.emplace_back(code,static_cast<std::int32_t>(std::stoi(value)));
        else raw.groups.emplace_back(code,value);
    }
    if(raw.groups.size()!=16u||raw.groups[11].code()!=280||raw.groups[11].i_val()!=0
        ||raw.groups[15].code()!=280||raw.groups[15].i_val()!=1)return 2;
    const auto audit=dx_attdef_source::audit(raw);
    dx_iface adapter;dx_data data;if(!adapter.fileImport(argv[1],&data,false))return 2;
    unsigned count=0;bool lock=false;int version=-1;
    for(const auto* block:data.blocks)if(block)for(const auto* entity:block->ent)
        if(entity&&entity->handle==0x6f8u) {
            const auto* attdef=dynamic_cast<const DRW_Attdef*>(entity);if(!attdef)return 2;
            ++count;lock=attdef->lockPosition;version=attdef->attVersion;
        }
    unsigned rows=0;bool pair=false,replay=false,profile=false,sourceRoles=false;
    DxIfaceTableSourceTestAccess::inspect(data,rows,pair,replay,profile,sourceRoles);
    const bool roles=audit.complete()&&audit.spans.size()==16u
        &&audit.spans[11].field==dx_attdef_source::Field::ReservedDefault
        &&audit.spans[15].field==dx_attdef_source::Field::Attribute;
    std::cout<<"groups="<<raw.groups.size()<<"; rejectedGroup="<<audit.rejectedGroup
        <<"; ambiguous="<<(audit.reason==dx_attdef_source::Reason::AmbiguousVersion)
        <<"; roles="<<roles<<"; capturedRows="<<rows<<"; pair="<<pair<<"; replay="<<replay
        <<"; capturedProfile="<<profile<<"; capturedRoles="<<sourceRoles<<"; callbackCount="<<count<<"; lockPosition="<<lock<<"; version="<<version<<'\n';
    return roles&&count==1u&&lock&&version==0&&rows==1u&&pair&&replay&&profile&&sourceRoles?0:1;
}

