#include "intern/dxfparserlimits.h"
#include "dwg2dxf/dx_attdef_source_profile.h"
#include "dwg2dxf/dx_iface.h"
#include "dwg2dxf/dx_data.h"
#include <cstdint>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
class DxIfaceTableSourceTestAccess {
public:
    static void inspect(const dx_data& data,unsigned& selected,bool& matched,bool& identities,bool& sourceRoles) {
        for(const auto& audit:data.m_tableDxfSource.entitiesCompoundAudits)if(audit&&audit->physical)
            for(const auto& proof:audit->proofs) {
                if(proof.first>=audit->members.size()||audit->members[proof.first].self!=0x704u)continue;
                ++selected;matched=proof.state==decltype(proof.state)::Matched&&proof.compound&&proof.modeledMatched&&proof.profilesMatched&&proof.spaceMatched;
                if(proof.next!=proof.first+3u||proof.next>audit->members.size()||proof.profiles.size()!=3u||proof.next>audit->physical->records.size())continue;
                const auto& a=audit->members[proof.first];const auto& b=audit->members[proof.first+1u];const auto& c=audit->members[proof.first+2u];
                identities=a.self==0x704u&&a.owner==0x1fu&&b.self==0x705u&&b.owner==0x704u&&c.self==0x706u&&c.owner==0x704u;
                const auto& physical=audit->physical->records[proof.first+1u];const auto& profile=proof.profiles[1u];
                sourceRoles=physical.groups.size()==15u&&profile.complete()&&profile.spans.size()==15u
                    &&profile.spans[11].code==280&&profile.spans[11].field==dx_attdef_source::Field::ReservedDefault
                    &&profile.spans[14].code==280&&profile.spans[14].field==dx_attdef_source::Field::Attribute;
            }
    }
};
int main(int argc,char** argv) {
    if(argc!=4)return 2;const auto version=std::string(argv[2])=="1024"?DRW::AC1024:std::string(argv[2])=="1027"?DRW::AC1027:DRW::AC1032;
    std::ifstream input(argv[1],std::ios::binary);if(!input)return 2;input.seekg(std::stoll(argv[3]));std::string bytes(205,'\0');input.read(&bytes[0],205);if(input.gcount()!=205)return 2;
    std::istringstream stream(bytes);std::string codeText,value;DRW_RawDxfObject raw;raw.name="ATTRIB";raw.handle=0x705u;raw.parentHandle=0x704u;raw.m_version=version;
    while(std::getline(stream,codeText)&&std::getline(stream,value)) {
        const int code=std::stoi(codeText);if(code==0)continue;
        if(code==10||code==20||code==30||code==40)raw.groups.emplace_back(code,std::stod(value));
        else if(code==70||code==280)raw.groups.emplace_back(code,static_cast<std::int32_t>(std::stoi(value)));
        else raw.groups.emplace_back(code,value);
    }
    if(raw.groups.size()!=15u||raw.groups[11].code()!=280||raw.groups[11].i_val()!=0||raw.groups[14].code()!=280||raw.groups[14].i_val()!=1)return 2;
    const auto audit=dx_attdef_source::audit(raw,false);dx_iface adapter;dx_data data;if(!adapter.fileImport(argv[1],&data,false))return 2;
    unsigned parents=0u,children=0u;bool lock=false,footer=false;int attVersion=-1;
    const auto inspect=[&](const dx_ifaceBlock* block) {if(block)for(const auto* entity:block->ent)if(entity&&entity->handle==0x704u) {
        const auto* insert=dynamic_cast<const DRW_Insert*>(entity);if(!insert)continue;++parents;footer=insert->seqEndEntity&&insert->seqEndEntity->handle==0x706u;
        for(const auto& a:insert->attlist)if(a&&a->handle==0x705u){++children;lock=a->lockPosition;attVersion=a->attVersion;}
    }};
    inspect(data.mBlock);for(const auto* block:data.blocks)inspect(block);
    const bool roles=audit.complete()&&audit.spans.size()==15u&&audit.spans[11].field==dx_attdef_source::Field::ReservedDefault&&audit.spans[14].field==dx_attdef_source::Field::Attribute;
    unsigned selected=0;bool matched=false,identities=false,sourceRoles=false;
    DxIfaceTableSourceTestAccess::inspect(data,selected,matched,identities,sourceRoles);
    std::cout<<"selected="<<selected<<"; matched="<<matched<<"; identities="<<identities<<"; sourceRoles="<<sourceRoles<<"; roles="<<roles<<"; groups="<<raw.groups.size()<<"; rejectedGroup="<<audit.rejectedGroup<<"; ambiguous="<<(audit.reason==dx_attdef_source::Reason::AmbiguousVersion)
        <<"; parents="<<parents<<"; children="<<children<<"; footer="<<footer<<"; lock="<<lock<<"; version="<<attVersion<<'\n';
    return roles&&parents==1u&&children==1u&&footer&&lock&&attVersion==0&&selected==1u&&matched&&identities&&sourceRoles?0:1;
}
